sys_script_vtable.script:
(function executeQuery(v_table, v_query) {
	/* global GlideRecord, GlideDateTime, GlideDuration */
	/* eslint no-undef: "error" */

	const STATE = {
		CANCELLED: 4
	};

	const executionGr = new GlideRecord('sys_execution_tracker');
	executionGr.addQuery('name', 'STARTSWITH', 'Intrux Code Search: ');
	executionGr.addNullQuery('parent');
	executionGr.addQuery('state', '!=', STATE.CANCELLED);
	if (v_query.isGet()) {
		executionGr.addQuery('sys_id', v_query.getSysId());
		executionGr.setLimit(1);
	} else {
		executionGr.setLimit(100);
	}

	executionGr.orderByDesc('sys_created_on');
	executionGr.query();
	while (executionGr.next()) {
		const completionTime = executionGr.completion_time ? new GlideDateTime(executionGr.completion_time) : new GlideDateTime();
		const duration = completionTime.getNumericValue() - new GlideDateTime(executionGr.start_time).getNumericValue();
		v_table.addRow({
			sys_id: executionGr.getUniqueValue(),
			term: executionGr.name.toString().substring('Intrux Code Search: '.length),
			scope: executionGr.source_table == 'sys_scope' ? executionGr.source : '',
			duration: new GlideDuration(duration),
			sys_created_on: executionGr.sys_created_on,
			sys_created_by: executeQuery.sys_created_by,
			actions: '1846f3c2837e36504967cbb6feaad399'
		});
	}

})(v_table, v_query); /* global v_table, v_query */

